function main(args) pi=p.create();p.UI_ForceLegsAnim(pi,p.LEGS_JUMP);print("legs "+str(pi.legsAnim)+" "+str(pi.legsAnimationTimer));pi.pendingLegsAnim=22;p.UI_SetLegsAnim(pi,19);print("legs_pending "+str(pi.legsAnim)+" "+str(pi.pendingLegsAnim));p.UI_ForceTorsoAnim(pi,p.TORSO_GESTURE);print("torso_gesture "+str(pi.torsoAnim)+" "+str(pi.torsoAnimationTimer));p.UI_ForceTorsoAnim(pi,p.TORSO_ATTACK);print("torso_attack "+str(pi.torsoAnim)+" "+str(pi.torsoAnimationTimer));s=p.UI_SwingAngles(90.0,25.0,90.0,0.3,0.0,false,16);print("swing "+str(n.trunc32(s[0]*1000))+" 1");pi.barrelTime=0;pi.barrelAngle=0.0;pi.barrelSpinning=false;pi.torsoAnim=p.TORSO_ATTACK;a=p.UI_MachinegunSpinAngle(pi,100);print("spin "+str(n.trunc32(a*1000))+" 1 "+str(pi.barrelTime)+" "+str(n.trunc32(pi.barrelAngle*1000)));pi.torsoAnim=p.TORSO_STAND;a=p.UI_MachinegunSpinAngle(pi,200);print("coast "+str(n.trunc32(a*1000))+" 0 "+str(pi.barrelTime)+" "+str(n.trunc32(pi.barrelAngle*1000)));return 0 end function
